"use client";

import { useState, useEffect } from "react";
import { useNavigate, useLocation } from "react-router-dom";
import {
  Home,
  LogOut,
  User,
  ChevronLeft,
  ChevronRight,
  Menu,
  ChevronDown,
  Users,
  UserCheck,
  GraduationCap,
  ClipboardList,
  Building2,
  Calendar,
  FileText,
  MapPin,
  Package,
  FileCheck,
  Truck,
  FileMinus,
  UserCog,
} from "lucide-react";

export default function Sidebar({ isCollapsed, setIsCollapsed, closeMenu }) {
  const navigate = useNavigate();
  const location = useLocation();
  const [isMobile, setIsMobile] = useState(false);
  const [isAdminOpen, setIsAdminOpen] = useState(false);
  const [isAbsenceOpen, setIsAbsenceOpen] = useState(false);
  const [isStockOpen, setIsStockOpen] = useState(false);

  useEffect(() => {
    const checkIfMobile = () => {
      setIsMobile(window.innerWidth < 768);
      if (window.innerWidth < 768) {
        setIsCollapsed(true);
      }
    };

    checkIfMobile();
    window.addEventListener("resize", checkIfMobile);
    return () => window.removeEventListener("resize", checkIfMobile);
  }, [setIsCollapsed]);

  useEffect(() => {
    const adminRoutes = ["/Candidates", "/Selected", "/Interns", "/CriteriaTable", "/PaymentTracking"];
    const absenceRoutes = ["/AbsenceRequests", "/deputy/submit-report"];
    const stockRoutes = ["/Zones", "/ManageProducts", "/ManageBons", "/ManageSortie", "/ManageSortieBons"];
    if (adminRoutes.includes(location.pathname)) {
      setIsAdminOpen(true);
    }
    if (absenceRoutes.includes(location.pathname)) {
      setIsAbsenceOpen(true);
    }
    if (stockRoutes.includes(location.pathname)) {
      setIsStockOpen(true);
    }
  }, [location.pathname]);

  const handleLogout = () => {
    localStorage.removeItem("token");
    navigate("/");
  };

  const AdministrationItems = [
    { title: "Candidats", icon: Users, href: "/Candidates" },
    { title: "Sélectionnés", icon: UserCheck, href: "/Selected" },
    { title: "Stagiaires", icon: GraduationCap, href: "/Interns" },

    { title: "anciens stagiaires", icon: GraduationCap, href: "/FormerInterns" },
    { title: "Tableau des critères", icon: ClipboardList, href: "/CriteriaTable" },
    { title: "Suivi des paiements", icon: ClipboardList, href: "/PaymentTracking" },
  ];

  const AbsenceItems = [
